namespace gui_forms {

// TableLayoutPanelCompat's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/table_layout_panel_compat.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// What a child that does not fit the authored grid does: add rows, add columns, or stay out (fixed size).
template <typename Declaring>
struct TableLayoutGrowCapability {
    PropertyCell<TableLayoutGrowStyle, TableLayoutGrowCapability<Declaring>> grow_style{TableLayoutGrowStyle::add_rows};

    static void assign(TableLayoutGrowCapability& capability, TableLayoutGrowStyle incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.grow_style), incoming);
        if (!capability.grow_style.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.grow_style));
    }
};

// The lines around and between the cells: none, single, inset or outset.
template <typename Declaring>
struct TableLayoutCellBorderCapability {
    PropertyCell<TableCellBorderStyle, TableLayoutCellBorderCapability<Declaring>> cell_border_style{TableCellBorderStyle::none};

    static void assign(TableLayoutCellBorderCapability& capability, TableCellBorderStyle incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.cell_border_style), incoming);
        if (!capability.cell_border_style.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.cell_border_style));
    }
};

// The space between neighbouring columns (width) and rows (height); each finite and between zero and 256, else std::invalid_argument.
template <typename Declaring>
struct TableLayoutTrackSpacingCapability {
    PropertyCell<Size, TableLayoutTrackSpacingCapability<Declaring>> track_spacing{Size{}};

    static void assign(TableLayoutTrackSpacingCapability& capability, Size incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.track_spacing), incoming);
        if (!capability.track_spacing.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.track_spacing));
    }
};

// The number of columns, 1 through 64 (else std::out_of_range); the column styles follow it. set_column_styles also sets it. A view onto the table's count.
template <typename Declaring>
struct TableLayoutColumnCountCapability {
    PropertyView<std::size_t, TableLayoutColumnCountCapability<Declaring>> column_count;

    static void assign(TableLayoutColumnCountCapability& capability, std::size_t incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.column_count), std::move(incoming));
    }

    static std::size_t read(const TableLayoutColumnCountCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        std::size_t current = control.read_view(capability.column_count);
        return current;
    }
};

// The number of rows, 1 through 64 (else std::out_of_range); the row styles follow it. set_row_styles also sets it. A view onto the table's count.
template <typename Declaring>
struct TableLayoutRowCountCapability {
    PropertyView<std::size_t, TableLayoutRowCountCapability<Declaring>> row_count;

    static void assign(TableLayoutRowCountCapability& capability, std::size_t incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.row_count), std::move(incoming));
    }

    static std::size_t read(const TableLayoutRowCountCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        std::size_t current = control.read_view(capability.row_count);
        return current;
    }
};

// TableLayoutGrowStyle as a property value; defined beside TableLayoutPanelCompat's table.
template <>
struct PropertyValueTraits<TableLayoutGrowStyle> {
    static PropertyType type();
    static BindingValue to_binding(TableLayoutGrowStyle value);
    static TableLayoutGrowStyle from_binding(const BindingValue& value);
};

// TableCellBorderStyle as a property value; defined beside TableLayoutPanelCompat's table.
template <>
struct PropertyValueTraits<TableCellBorderStyle> {
    static PropertyType type();
    static BindingValue to_binding(TableCellBorderStyle value);
    static TableCellBorderStyle from_binding(const BindingValue& value);
};

// Every TableLayoutPanelCompat capability, in the order the declaring class takes them.
template <typename Declaring>
struct TableLayoutPanelCompatCapabilities : public TableLayoutGrowCapability<Declaring>,
                                            public TableLayoutCellBorderCapability<Declaring>,
                                            public TableLayoutTrackSpacingCapability<Declaring>,
                                            public TableLayoutColumnCountCapability<Declaring>,
                                            public TableLayoutRowCountCapability<Declaring> {};

} // namespace gui_forms
